import React, { useEffect, useState } from 'react';
import { Outlet, NavLink, useNavigate, useLocation } from 'react-router-dom';

// Import Assets (Giữ nguyên path như Admin để đồng bộ)
import logoBgImg from '../../assets/nen_ten_web.jpg'; 
import mainBgImg from '../../assets/nen_nen.jpg';

const TrangChuCuDan = () => {
    const navigate = useNavigate();
    const location = useLocation();

    // 1. ĐẦU CHỜ BACKEND: Kiểm tra trạng thái đã khai báo thông tin chưa
    // Hiện tại mình dùng localStorage để giả lập, sau này bạn dùng API check DB
    const [isProfileUpdated, setIsProfileUpdated] = useState(() => {
        return localStorage.getItem('isProfileUpdated') === 'true';
    });

    const menuItems = [
        { name: 'Thông báo', path: 'thong-bao' },
        { name: 'Xem hoá đơn', path: 'hoa-don' },
        { name: 'Nhắn tin', path: 'nhan-tin' },
        { name: 'Gửi yêu cầu bảo trì', path: 'bao-tri' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien' },
        { name: 'Đăng ký bãi đỗ xe', path: 'dang-ky-bai-do-xe' },
        { name: 'Thông tin cá nhân', path: 'thong-tin' },
    ];

    // 2. LOGIC ĐIỀU HƯỚNG TỐI ƯU BACKEND
    useEffect(() => {
        // Nếu vừa đăng nhập vào trang chủ (path là /dashboard-cu-dan hoặc /dashboard-cu-dan/)
        if (location.pathname === '/dashboard-cu-dan' || location.pathname === '/dashboard-cu-dan/') {
            if (!isProfileUpdated) {
                // Nếu chưa có thông tin -> Bắt buộc xuống Thông tin cá nhân
                navigate('/dashboard-cu-dan/thong-tin');
            } else {
                // Nếu rồi -> Vào Thông báo
                navigate('/dashboard-cu-dan/thong-bao');
            }
        }
    }, [isProfileUpdated, location.pathname, navigate]);

    return (
        <div style={{
            display: 'flex', height: '100vh', padding: '20px', gap: '20px', 
            backgroundImage: `url(${mainBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', boxSizing: 'border-box'
        }}>
            {/* Sidebar */}
            <aside style={styles.sidebar} className="glass-sidebar">
                <div style={{...styles.logoWrapper, backgroundImage: `url(${logoBgImg})`}}>
                    <h1 style={styles.logoText}>A&RMS</h1>
                </div>

                <nav style={styles.navStack}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-cu-dan/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navBtn,
                                backgroundColor: isActive ? 'rgba(139, 94, 94, 0.9)' : '#fff',
                                color: isActive ? '#fff' : '#333',
                                // Hiệu ứng nhẹ để nhấn mạnh mục Thông tin nếu chưa cập nhật
                                border: (!isProfileUpdated && item.path === 'thong-tin') ? '2px solid #fbc02d' : 'none'
                            })}
                        >
                            {item.name}
                        </NavLink>
                    ))}
                </nav>

                {/* Nút đăng xuất giả lập */}
                <button 
                    onClick={() => { localStorage.clear(); window.location.href = '/login'; }}
                    style={styles.logoutBtn}
                >
                    Đăng xuất
                </button>
            </aside>

            {/* Content Area */}
            <div style={styles.rightContent}>
                <header style={styles.headerRow}>
                    <div className="glass-sidebar" style={styles.titleBox}>Hệ thống cư dân A&RMS</div>
                    <div className="glass-sidebar" style={styles.adminBox}>Cư dân</div>
                </header>
                <main style={styles.contentMain}>
                    <Outlet />
                </main>
            </div>
        </div>
    );
};

// Styles kế thừa từ Admin và tinh chỉnh
const styles = {
    sidebar: { width: '280px', borderRadius: '30px', padding: '25px', display: 'flex', flexDirection: 'column' },
    logoWrapper: { 
        height: '110px', marginBottom: '30px', display: 'flex', alignItems: 'center', 
        justifyContent: 'center', borderRadius: '20px', backgroundSize: 'cover', 
        backgroundPosition: 'center', boxShadow: '0 4px 15px rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.2)' 
    },
    logoText: { color: '#fff', fontSize: '35px', fontWeight: '900', textShadow: '2px 2px 10px rgba(0,0,0,0.8)', margin: 0 },
    navStack: { display: 'flex', flexDirection: 'column', gap: '10px', flex: 1 },
    navBtn: { padding: '15px 20px', borderRadius: '25px', textDecoration: 'none', fontWeight: '600', fontSize: '13px', textAlign: 'center', transition: '0.3s' },
    logoutBtn: { marginTop: '20px', padding: '12px', borderRadius: '20px', border: 'none', background: 'rgba(255,255,255,0.2)', color: '#fff', cursor: 'pointer', fontWeight: 'bold' },
    rightContent: { flex: 1, display: 'flex', flexDirection: 'column', gap: '20px' },
    headerRow: { display: 'flex', gap: '20px', height: '60px' },
    titleBox: { flex: 1, borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontWeight: 'bold' },
    adminBox: { width: '150px', borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontWeight: 'bold' },
    contentMain: { flex: 1, display: 'flex' }
};

export default TrangChuCuDan;
